ACMsg.MICROBIT_RESET = "Программно сбрасывает плату micro:bit, эквивалентно нажатию кнопки сброса.";
ACMsg.MICROBIT_SLEEP = "Приостанавливает выполнение программы на <b>ms</b> миллисекунд.";
ACMsg.MICROBIT_RUNNING_TIME = "Возвращает время, прошедшее с запуска платы, в миллисекундах.";
ACMsg.MICROBIT_PANIC = "Отображает ошибку <b>error_code</b> на светодиодной матрице и перезагружает плату.";
ACMsg.MICROBIT_TEMPERATURE = "Возвращает приблизительную температуру платы в градусах Цельсия.";
ACMsg.MICROBIT_SET_VOLUME = "Устанавливает глобальную громкость звука в значение <b>volume</b> от 0 до 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Записывает содержимое буфера <b>buf</b> в светодиодную ленту WS2812, подключённую к <b>pin</b>. Буфер должен быть типа bytes или bytearray.";
ACMsg.MICROBIT_RUN_EVERY = "Планирует выполнение функции с интервалом, заданным аргументами времени. Каждый аргумент соответствует своей единице времени, и они суммируются. Например, <b>run_every(min=1, s=30)</b> запускает callback каждые полторы минуты. Если внутри callback возникает исключение, функция снимается с расписания. Чтобы этого избежать, перехватывайте исключения с помощью <b>try/except</b>. <b>run_every</b> также можно использовать как декоратор — поместите его над определением функции, чтобы запланировать исполнение.";
ACMsg.MICROBIT_SCALE = "Преобразует <b>value</b> из диапазона, заданного <b>from_low</b> и <b>from_high</b>, в новый диапазон, заданный <b>to_low</b> и <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Планирует выполнение функции с интервалом, заданным аргументами времени. Каждый аргумент соответствует своей единице времени, и они суммируются. Например, <b>run_every(min=1, s=30)</b> запускает callback каждые полторы минуты. Если в callback возникает исключение, оно снимается с расписания. Чтобы этого избежать, обрабатывайте исключения с помощью <b>try/except</b>. <b>run_every</b> также можно использовать как обычную функцию, передав планируемую функцию в качестве первого аргумента.";
ACMsg.MICROBIT_DISPLAY = "Этот модуль управляет 5x5 светодиодным дисплеем на передней панели платы. Его можно использовать для отображения изображений, анимаций и текста.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Возвращает яркость светодиода в столбце <b>x</b> и строке <b>y</b> в виде целого числа от <b>0</b> (выключен) до <b>9</b> (максимум).";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Устанавливает яркость светодиода в столбце <b>x</b> и строке <b>y</b> в <b>value</b> — целое число от <b>0</b> до <b>9</b>.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Устанавливает яркость всех светодиодов в <b>0</b> (выключено).";
ACMsg.MICROBIT_DISPLAY_SHOW = "Отображает <b>image</b>.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "Если <b>image</b> — строка, число с плавающей точкой или целое число, отображаются буквы/цифры поочерёдно. В противном случае, если <b>image</b> — итерируемая последовательность изображений, они показываются по очереди. Между каждым символом, цифрой или изображением ставится пауза <b>delay</b> миллисекунд. Если <b>wait</b> равно <b>True</b>, функция блокирует выполнение до окончания анимации; иначе анимация идёт в фоне. Если <b>loop</b> равно <b>True</b>, анимация будет повторяться бесконечно. Если <b>clear</b> равно <b>True</b>, дисплей будет очищен после завершения итерации. Обратите внимание, что аргументы <b>wait</b>, <b>loop</b> и <b>clear</b> должны передаваться по именам.";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Прокручивает <b>text</b> по горизонтали на дисплее. Если <b>text</b> — целое или вещественное число, оно сначала приводится к строке с помощью <b>str()</b>. Параметр <b>delay</b> регулирует скорость прокрутки. Если <b>wait</b> равно <b>True</b>, функция блокирует выполнение до окончания анимации; иначе анимация идёт в фоне. Если <b>loop</b> равно <b>True</b>, анимация будет повторяться бесконечно. Если <b>monospace</b> равно <b>True</b>, символы займут по <b>5</b> столбцов пикселей, иначе между символами при прокрутке будет ровно <b>1</b> пустой столбец пикселей. Обратите внимание, что аргументы <b>wait</b>, <b>loop</b> и <b>monospace</b> должны передаваться по именам.";
ACMsg.MICROBIT_DISPLAY_ON = "Используйте <b>on()</b> для включения дисплея.";
ACMsg.MICROBIT_DISPLAY_OFF = "Используйте <b>off()</b> для выключения дисплея (это позволяет повторно использовать GPIO-пины, связанные с дисплеем, для других задач).";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Возвращает <b>True</b>, если дисплей включён, иначе возвращает <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Использует светодиоды дисплея в режиме обратного смещения для измерения освещённости, падающей на дисплей. Возвращает целое число от <b>0</b> до <b>255</b>, где большее значение означает больше света.";
ACMsg.MICROBIT_IMAGE = "Класс <b>Image</b> используется для создания изображений, которые легко отображать на светодиодной матрице устройства. Получив объект изображения, его можно показать через API <b>display</b>."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "Если в качестве <b>string</b> используется строка, она должна состоять из цифр от 0 до 9, расположенных в строках, описывающих изображение, например: <pre>\n\nimage = Image('09090:'\n\t '99999:'\n\t '99999:'\n\t '09990:'\n\t '00900:')\n</pre> создаст изображение 5x5 в форме буквы X. Конец строки обозначается двоеточием."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "Этот метод создаёт пустое изображение с <b>width</b> столбцами и <b>height</b> строками. Параметр <b>buffer</b> может быть массивом размера <b>width</b> * <b>height</b>, содержащим целые числа от 0 до 9. Например: <pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\nили\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre> создаёт изображение 2x2 яркости 9.";
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Встроенная последовательность изображений (анимация), например <b>Image.ALL_CLOCKS</b> или <b>Image.ALL_ARROWS</b>.";
